printf "\033[0;36m\033[1m*** Start Testing ***\033[0m\n";

printf "\033[0;36m\033[1m# Parsing Booting Logs ... \033[0m\n";
sleep 0.5
cat /unitree/robot/basic/startup
echo "------------------\n"

printf "\033[0;36m\033[1m# Displaying Machine Information ... \033[0m\n";
sleep 0.5
SN=$(cat /unitree/robot/basic/code)
echo "machine SN:$SN"
bluetooth_code=$(cat /unitree/robot/basic/bluetooth)
echo "mechine bluetooth code:$bluetooth_code"
wifi_mode=$(cat /unitree/etc/wifi/WIFI_MODE)
echo "mechine wifi mode:$wifi_mode"
echo "------------------\n"

printf "\033[0;36m\033[1m# Testing Video Interfaces ... \033[0m\n";
sleep 0.5
ls /dev/video*
echo "------------------\n"

printf "\033[0;36m\033[1m# Testing Audio Interfaces ... \033[0m\n";
sleep 0.5
aplay -l | grep USB
echo "------------------\n"

printf "\033[0;36m\033[1m# Testing Network Connection ... \033[0m\n";
sleep 0.5
printf "\033[0;35m\033[1m\nInner Network: eth0\033[0m\n";
ifconfig eth0 | grep inet | sed -e 's/^\s*//' -e '/^$/d'

sleep 0.5
printf "\033[0;35m\033[1m\nAP Network: wlan1\033[0m\n";
ifconfig wlan1 | grep inet | sed -e 's/^\s*//' -e '/^$/d'

sleep 0.5
printf "\033[0;35m\033[1m\n4G Network: wwan0\033[0m\n";
ifconfig wwan0 | grep -q inet
if [ $? -eq 0 ]
then
    ifconfig wwan0 | grep -q inet | sed -e 's/^\s*//' -e '/^$/d'
    printf "\033[0;32m\033[1m4G network found, start ping test\033[0m\n";
    #检测4G卡绑定的IP或域名
    timeout 2 ping -c1 -I wwan0 robot-mqtt.unitree.com > /dev/null
    if [ $? -eq 0 ] 
    then printf "\033[0;32m\033[1mrobot-mqtt.unitree.com Passed\033[0m\n";
    else printf "\033[0;31m\033[1mrobot-mqtt.unitree.com Failed\033[0m\n";
    fi

    timeout 2 ping -c1 -I wwan0 robot-api.unitree.com > /dev/null
    if [ $? -eq 0 ] 
    then printf "\033[0;32m\033[1mrobot-api.unitree.com Passed\033[0m\n";
    else printf "\033[0;31m\033[1mrobot-api.unitree.com Failed\033[0m\n";
    fi

    timeout 2 ping -c1 -I wwan0 turn.unitree.com > /dev/null
    if [ $? -eq 0 ] 
    then printf "\033[0;32m\033[1mturn.unitree.com Passed\033[0m\n";
    else printf "\033[0;31m\033[1mturn.unitree.com Failed\033[0m\n";
    fi

    timeout 2 ping -c1 -I wwan0 turn01.unitree.com > /dev/null
    if [ $? -eq 0 ] 
    then printf "\033[0;32m\033[1mturn01.unitree.com Passed\033[0m\n";
    else printf "\033[0;31m\033[1mturn01.unitree.com Failed\033[0m\n";
    fi

    timeout 2 ping -c1 -I wwan0 global-robot-mqtt.unitree.com > /dev/null
    if [ $? -eq 0 ] 
    then printf "\033[0;32m\033[1mglobal-robot-mqtt.unitree.com Passed\033[0m\n";
    else printf "\033[0;31m\033[1mglobal-robot-mqtt.unitree.com Failed\033[0m\n";
    fi

    timeout 2 ping -c1 -I wwan0 global-robot-api.unitree.com > /dev/null
    if [ $? -eq 0 ] 
    then printf "\033[0;32m\033[1mglobal-robot-api.unitree.com Passed\033[0m\n";
    else printf "\033[0;31m\033[1mglobal-robot-api.unitree.com Failed\033[0m\n";
    fi

    timeout 2 ping -c1 -I wwan0 global-turn.unitree.com > /dev/null
    if [ $? -eq 0 ] 
    then printf "\033[0;32m\033[1mglobal-turn.unitree.com Passed\033[0m\n";
    else printf "\033[0;31m\033[1mglobal-turn.unitree.com Failed\033[0m\n";
    fi

    timeout 2 ping -c1 -I wwan0 global-turn01.unitree.com > /dev/null
    if [ $? -eq 0 ] 
    then printf "\033[0;32m\033[1mglobal-turn01.unitree.com Passed\033[0m\n";
    else printf "\033[0;31m\033[1mglobal-turn01.unitree.com Failed\033[0m\n";
    fi

    timeout 2 ping -c1 -I wwan0 unitree-firmware.oss-accelerate.aliyuncs.com > /dev/null
    if [ $? -eq 0 ] 
    then printf "\033[0;32m\033[1munitree-firmware.oss-accelerate.aliyuncs.com Passed\033[0m\n";
    else printf "\033[0;31m\033[1munitree-firmware.oss-accelerate.aliyuncs.com Failed\033[0m\n";
    fi

    timeout 2 ping -c1 -I wwan0 unitree-firmware-cdn.unitree.com > /dev/null
    if [ $? -eq 0 ] 
    then printf "\033[0;32m\033[1munitree-firmware-cdn.unitree.com Passed\033[0m\n";
    else printf "\033[0;31m\033[1munitree-firmware-cdn.unitree.com Failed\033[0m\n";
    fi

else
    printf "\033[0;31m\033[1m4G network not found\033[0m\n";
fi

printf "\033[0;35m\033[1m\nSTA Network: wlan0\033[0m\n";
ifconfig wlan0 | grep inet | sed -e 's/^\s*//' -e '/^$/d'
#检测4G卡绑定的IP或域名
timeout 2 ping -c1 -I wlan0 robot-mqtt.unitree.com > /dev/null
if [ $? -eq 0 ] 
then printf "\033[0;32m\033[1mInternet Connected\033[0m\n";
else printf "\033[0;31m\033[1mInternet Disconnected\033[0m\n";
fi
echo "------------------\n"

printf "\033[0;36m\033[1m# Testing System Bluetooth ... \033[0m\n";
sleep 0.2
systemctl status bluetooth | sed -n '3s/^[[:blank:]]*//p'
printf "\n";
